// Fixed Vietnamese text used when the AI is off or unreachable. Ported from agent/FallbackExplainer.java,
// agent/NextStep.java and risk/RightsGuide.java. Rights text is never generated by AI because it must be exact.
import { percent, vnd } from './format';

export const NEXT_STEPS = {
  SEEK_LICENSED_LENDER:
    'Cân nhắc vay ở đơn vị được cấp phép và so sánh lãi suất trước khi quyết định.',
  REPORT_HARASSMENT:
    'Nếu bị đòi nợ bằng đe dọa hoặc quấy rối, hãy lưu bằng chứng và phản ánh với cơ quan chức năng.',
  SEEK_LEGAL_ADVICE: 'Nên hỏi ý kiến người có chuyên môn pháp lý trước khi ký hoặc trả thêm.',
  NO_ACTION_NEEDED:
    'Bạn không cần làm thêm gì ngay lúc này. Hãy giữ lại hợp đồng và biên lai.',
};

export const DISCLAIMER =
  'Công cụ chỉ cung cấp thông tin tham khảo dựa trên số liệu bạn nhập, không thay thế tư vấn pháp lý chính thức ' +
  'và không xác minh hợp đồng có thật hay không.';

const comparison = (riskCode, days, cap20, cap100) => {
  const ref20 = `mức ${vnd(cap20)}, là mốc tham khảo 20%/năm tính cho ${days} ngày vay`;
  switch (riskCode) {
    case 'LICENSED_LOW':
      return [`Tiền lãi này không vượt ${ref20}.`, 'NO_ACTION_NEEDED'];
    case 'LICENSED_HIGH':
      return [
        `Tiền lãi này cao hơn ${ref20}. Mốc này có áp dụng cho công ty tài chính được cấp phép hay không cần luật sư xác nhận.`,
        'SEEK_LICENSED_LENDER',
      ];
    case 'LICENSED_VERY_HIGH':
      return [`Tiền lãi này vượt xa ${ref20}. Hãy kiểm tra lại các con số bạn đã nhập.`, 'SEEK_LEGAL_ADVICE'];
    case 'SERIOUS':
      return [
        `Tính cho ${days} ngày vay, tiền lãi này vượt cả mốc 20%/năm (${vnd(cap20)}) và mốc 100%/năm (${vnd(cap100)}), và không tìm thấy bên cho vay trong danh sách cấp phép. Đây là dấu hiệu cần đặc biệt thận trọng.`,
        'SEEK_LEGAL_ADVICE',
      ];
    case 'RISK_SIGNALS':
      return [
        'Bạn đã đánh dấu các dấu hiệu đáng ngờ và chưa xác minh được bên cho vay. Lãi suất thấp không có nghĩa là an toàn.',
        'SEEK_LEGAL_ADVICE',
      ];
    case 'NOT_FOUND':
      return [
        'Chưa tìm thấy bên cho vay trong danh sách cấp phép hiện có, nên chưa thể xác minh tư cách pháp lý của họ.',
        'SEEK_LEGAL_ADVICE',
      ];
    default:
      return ['Chưa xác định được bên cho vay nên chưa thể đối chiếu đầy đủ với quy định.', 'SEEK_LEGAL_ADVICE'];
  }
};

export function fallbackExplain({ termPercent, cap20, cap100, riskCode, principal, totalRepay, days }) {
  const explanation =
    `Bạn nhận ${vnd(principal)} và phải trả ${vnd(totalRepay)} sau ${days} ngày, ` +
    `tức trả thêm ${vnd(totalRepay - principal)}, bằng ${percent(termPercent)}% số tiền nhận được trong ${days} ngày đó.`;
  const [legalComparison, nextStep] = comparison(riskCode, days, cap20, cap100);
  return {
    explanation,
    legalComparison,
    nextStep,
    nextStepText: NEXT_STEPS[nextStep],
    ai: { mode: 'offline', note: '' },
  };
}

export function rightsForLevel(level) {
  const base = [
    'Bạn vẫn có nghĩa vụ trả khoản nợ gốc và phần lãi nằm trong giới hạn pháp luật cho phép.',
    'Việc đòi nợ bằng đe dọa, quấy rối hoặc liên hệ người thân, đồng nghiệp của bạn có thể là hành vi vi phạm pháp luật. ' +
      'Hãy lưu lại tin nhắn, ghi âm và hình ảnh làm bằng chứng.',
    'Bạn có thể phản ánh với công an phường/xã hoặc Cổng thông tin cảnh báo an ninh mạng khi bị đe dọa, quấy rối.',
  ];
  if (level === 'low') {
    return [
      'Hãy đọc kỹ hợp đồng và giữ lại bản sao điều khoản, lịch trả nợ và biên lai thanh toán.',
      'Đơn vị được cấp phép thường báo cáo dữ liệu tín dụng. Trả nợ đúng hạn giúp bạn giữ lịch sử tín dụng tốt.',
    ];
  }
  if (level === 'caution' || level === 'high' || level === 'unknown') {
    return [
      ...base,
      'Trước khi ký hoặc trả thêm, hãy yêu cầu bên cho vay cung cấp bằng văn bản: tên pháp lý, mã số doanh nghiệp, ' +
        'tổng số tiền phải trả và các loại phí.',
    ];
  }
  return [
    ...base,
    'Không cung cấp thêm ảnh giấy tờ, danh bạ hay quyền truy cập điện thoại cho ứng dụng không rõ nguồn gốc.',
    'Nên hỏi ý kiến người có chuyên môn pháp lý hoặc cơ quan chức năng trước khi quyết định.',
  ];
}
